const listReviewTallies = `-- name: ListReviewTallies :many
WITH released AS (
    SELECT
        v.task_id::uuid AS task_id,
        COUNT(DISTINCT v.round_id)::int AS rounds
    FROM
        reviews v
    WHERE
        v.released_at IS NOT NULL
    GROUP BY
        v.task_id
),
concluded AS (
    SELECT DISTINCT ON (v.task_id)
        v.task_id,
        v.verdict,
        n.snapshot_sha
    FROM
        reviews v
        JOIN review_rounds n ON n.id = v.round_id
    WHERE
        v.released_at IS NOT NULL
        AND v.verdict IN ('approved', 'changes_requested')
    ORDER BY
        v.task_id,
        n.ordinal DESC,
        v.released_at DESC
)
SELECT
    r.task_id,
    r.rounds,
    c.verdict,
    c.snapshot_sha
FROM
    released r
    LEFT JOIN concluded c ON c.task_id = r.task_id
`

